-- Align restored object privileges with the source database, removing privileges
-- inherited from different destination defaults. No business data is changed.
SET search_path = public, pg_catalog;
REVOKE ALL ON ALL TABLES IN SCHEMA public FROM PUBLIC, anon, authenticated, service_role;
REVOKE ALL ON ALL SEQUENCES IN SCHEMA public FROM PUBLIC, anon, authenticated, service_role;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA public, atm_private FROM PUBLIC, anon, authenticated, service_role;
